import type { Register } from 'claude-code'
import { installAll } from './trackers/index'

export const register: Register = (on) => {
  installAll(on)
}

files.hooks/trackers/index.ts:
import type { On } from 'claude-code'
import { installA } from './a'
import { installB } from './b'

/** One registry function. A new tracker adds one line here. */
export function installAll(on: On): void {
  installA(on)
  installB(on)
}

files.hooks/trackers/a.ts:
import type { On } from 'claude-code'

// An arrow const is a function too.
export const installA = (on: On): void => {
  on('tool.call', { tool: 'Bash' }, ($, e, next) => ({ deny: 'a-fired' }))
}

files.hooks/trackers/b.ts:
import type { On } from 'claude-code'

export function installB(on: On): void {
  // `$` is the hook's own parameter. Calls on it are literal.
  on('tool.call', { tool: 'Read' }, async ($, e, next) => {
    const id = await $.session.id()
    return { deny: `b-fired:${id}` }
  })
  on('turn.complete', ($, e, next) => next(e))
}
